  protected readonly checkIns = computed(() =>
    this.today.hasValue() ? this.today.value().checkIns : [],
  );
  protected readonly prompt = computed(() =>
    this.today.hasValue()
      ? promptState(
          this.today.value().promptTimes,
          this.checkIns(),
          this.clock.minutesOfDay(this.now()),
