    if (zone === null) {
      return;
    }

    await this.saving.run(
      true,
      async () => {
        const saved = await this.feelings.checkIn({
          zone,
          tags: this.tags(),
          note: this.note().trim(),
        });
        this.now.set(this.clock.now());
        this.savedAtMs.set(this.now());
        this.lastSaved.set(saved);
