import { Component, computed, inject, input } from '@angular/core';

import { parseIsoDate } from '../../../../../core/date-utils';
import { TranslatePipe } from '../../../../../core/i18n/translate.pipe';
import { TranslationService } from '../../../../../core/i18n/translation.service';
import {
  DosePeriod,
  LevelCount,
  groupByDosePeriod,
  regimenMedicines,
} from '../../../../../core/medicine-effects';
import {
  EffectLevel,
  MedicineEffectNote,
  SideEffectSeverity,
} from '../../../../../core/medicines.service';
import { TimeOfDayPipe } from '../../../../../core/time-of-day.pipe';
import { Card } from '../../../../../shared/card/card';

type Level = EffectLevel | SideEffectSeverity;

// Bar segment colours per level, worst to best read left to right as the scale is listed.
const LEVEL_COLOURS: Record<Level, string> = {
  Poor: 'bg-red-400 dark:bg-red-500',
  Okay: 'bg-amber-300 dark:bg-amber-500',
  Good: 'bg-emerald-500 dark:bg-emerald-400',
  None: 'bg-slate-300 dark:bg-slate-600',
  Mild: 'bg-amber-200 dark:bg-amber-700',
  Moderate: 'bg-orange-400 dark:bg-orange-500',
  Severe: 'bg-red-500 dark:bg-red-400',
};

interface BarSegment {
  value: string;
  count: number;
  percent: number;
  colour: string;
}

interface PeriodRow {
  period: DosePeriod;
  range: string;
  effects: { key: string; label: string; segments: BarSegment[] }[];
  sideEffects: { key: string; label: string; segments: BarSegment[] }[];
}

// The dose-period summary (docs/backend/analysis/medicine-effect-notes.md, Question 6): one block
// per run of days on the same regimen, each rated item as a stacked bar with its counts written
// out, so it reads (and prints) without a chart library.
@Component({
  selector: 'app-effect-periods',
  imports: [Card, TimeOfDayPipe, TranslatePipe],
  templateUrl: './effect-periods.html',
})
export class EffectPeriods {
  private readonly translation = inject(TranslationService);

  readonly notes = input.required<MedicineEffectNote[]>();
  // The medicine page's "last 3 months" line; a visit summary has its own period and leaves it out.
  readonly showIntro = input(true);

  // Printed under the periods, so the paper copy says what was left out. Empty in a visit summary,
  // whose notes arrive with the left-out medicines already removed.
  protected readonly notIncluded = computed(() =>
    regimenMedicines(this.notes())
      .filter((m) => m.isExcludedFromEffects)
      .map((m) => m.name)
      .join(', '),
  );

  protected readonly rows = computed((): PeriodRow[] => {
    const t = (key: string, params?: Record<string, string | number>) =>
      this.translation.translate(key, params);
    const locale = this.translation.language();
    const format = (date: string) =>
      parseIsoDate(date).toLocaleDateString(locale, { month: 'short', day: 'numeric' });

    return groupByDosePeriod(this.notes())
      .reverse()
      .map((period) => ({
        period,
        range:
          period.from === period.to
            ? format(period.from)
            : t('medicine.effects.periods.range', {
                from: format(period.from),
                to: format(period.to),
              }),
        effects: period.effects.map(({ area, counts }) => ({
          key: area,
          label: t(`medicine.effects.areas.${area}`),
          segments: this.segments(counts),
        })),
        sideEffects: period.sideEffects.map(({ kind, counts }) => ({
          key: kind,
          label: t(`medicine.effects.sideEffects.${kind}`),
          segments: this.segments(counts),
        })),
      }));
  });

  protected countsText(segments: BarSegment[], scale: 'levels' | 'severities'): string {
    return segments
      .filter((s) => s.count > 0)
      .map(
        (s) => `${this.translation.translate(`medicine.effects.${scale}.${s.value}`)} ${s.count}`,
      )
      .join(', ');
  }

  // groupByDosePeriod only keeps rated areas and side effects, so total is at least 1.
  private segments(counts: LevelCount<Level>[]): BarSegment[] {
    const total = counts.reduce((sum, c) => sum + c.count, 0);

    return counts.map(({ value, count }) => ({
      value,
      count,
      percent: (count / total) * 100,
      colour: LEVEL_COLOURS[value],
    }));
  }
}

import { Component, computed, inject, input, output, signal } from '@angular/core';

import { TranslatePipe } from '../../../../../core/i18n/translate.pipe';
import { regimenMedicines } from '../../../../../core/medicine-effects';
import { MedicineEffectNote, MedicinesService } from '../../../../../core/medicines.service';
import { Toggle } from '../../../../../shared/toggle/toggle';

// One switch per medicine in the summary's notes, to leave e.g. vitamin D out of the dose periods
// and the doctor visit summary (docs/backend/analysis/medicine-effect-inclusion.md). Listed from the
// notes, not the schedules, so a stopped medicine that still shapes old periods is there too.
@Component({
  selector: 'app-effect-inclusion',
  imports: [Toggle, TranslatePipe],
  templateUrl: './effect-inclusion.html',
})
export class EffectInclusion {
  private readonly medicines = inject(MedicinesService);

  readonly childId = input.required<string>();
  readonly notes = input.required<MedicineEffectNote[]>();
  // After a save, so the page reloads the notes (and with them the periods).
  readonly changed = output();

  protected readonly items = computed(() => regimenMedicines(this.notes()));
  protected readonly savingId = signal<string | null>(null);
  protected readonly error = signal<string | null>(null);

  protected async setIncluded(medicineId: string, included: boolean): Promise<void> {
    this.savingId.set(medicineId);
    this.error.set(null);

    try {
      await this.medicines.setEffectInclusion(this.childId(), medicineId, included);
      this.changed.emit();
    } catch {
      this.error.set('medicine.effects.inclusion.saveError');
    } finally {
      this.savingId.set(null);
    }
  }
}

